// Import required modules
const express = require('express');
const mongoose = require('mongoose');
const bcryptjs = require('bcryptjs');
const path = require('path');
// Initialize Express app
const app = express();
const PORT = 3000;
// Middleware for parsing JSON and form data
app.use(express.json());
app.use(express.urlencoded({ extended: true }));
// Static file serving
app.use(express.static("CSS"));
app.use(express.static("JS"));
app.use(express.static("images"));
// MongoDB Connection
mongoose
mongoose
.connect('mongodb://0.0.0.0/COLLAGE_CLUB_PLATFORM_APP')
.then(() => console.log('Connected to MongoDB'))
.catch((err) => console.error('MongoDB connection error:', err));
// Define Mongoose Schemas and Models
// Student Schema and Model
const studentSchema = new mongoose.Schema({
username: { type: String, required: true },
password: { type: String, required: true },
});
const Student = mongoose.model('Student', studentSchema);
// ClubAdmin Schema and Model
const ClubAdminSchema = new mongoose.Schema({
username: { type: String, required: true },
password: { type: String, required: true },
});
const ClubAdmin = mongoose.model('ClubAdmin', ClubAdminSchema);
// Other User Schema and Model
const otherSchema = new mongoose.Schema({
username: { type: String, required: true },
password: { type: String, required: true },
});
// Routes
// Serve Signup Page
app.get('/signup', (req, res) => {
res.sendFile(path.join(__dirname, 'views', 'signup.html'));
});
// Handle Signup Requests
app.post('/signup', async (req, res) => {
try {
const { userType, username, password } = req.body;
// Validate input
if (!username || !password || !userType) {
return res.status(400).json({ error: 'All fields are required.' });
}
let UserModel;
// Determine user type
if (userType === "Student") UserModel = Student;
else if (userType === "ClubAdmin") UserModel = ClubAdmin;
else return res.status(400).json({ error: 'Invalid user type.' });
// Check if user already exists
const existingUser = await UserModel.findOne({ username });
if (existingUser) {
return res.status(400).json({ error: 'Username already exists.' });
}
// Hash the password
const hashedPassword = await bcryptjs.hash(password, 10);
// Save user to the database
const newUser = new UserModel({ username, password: hashedPassword });
await newUser.save();
res.status(201).json({ message: 'User signed up successfully.' });
} catch (err) {
console.error('Error during signup:', err);
res.status(500).json({ error: 'Internal server error.' });
}
});
// Serve Login Page
app.get('/login', (req, res) => {
res.sendFile(path.join(__dirname, 'views', 'login.html'));
});
// Handle Login Requests
app.post('/login', async (req, res) => {
try {
const { userType, username, password } = req.body;
// Validate input
if (!username || !password || !userType) {
return res.status(400).json({ error: 'All fields are required.' });
}
let UserModel;
// Determine user type
if (userType === "Student") UserModel = Student;
else if (userType === "ClubAdmin") UserModel = ClubAdmin;
else return res.status(400).json({ error: 'Invalid user type.' });
// Find user in the database
const user = await UserModel.findOne({ username });
if (!user) {
return res.status(400).json({ error: 'Invalid username or password.' });
}
// Compare passwords
const isMatch = await bcryptjs.compare(password, user.password);
if (!isMatch) {
return res.status(400).json({ error: 'Invalid username or password.' });
}
res.status(200).json({ message: 'Login successful.' });
} catch (err) {
console.error('Error during login:', err);
res.status(500).json({ error: 'Internal server error.' });
}
});
// Additional Routes for Static Pages
app.get('/club-admin-dashboard', (req, res) => {
res.sendFile(path.join(__dirname, 'views', 'club-admin-dashboard.html'));
});
app.get('/student-dashboard', (req, res) => {
res.sendFile(path.join(__dirname, 'views', 'student-dashboard.html'));
});
// Start the Server
app.listen(PORT, () => {
console.log(`🚀 Server running on http://localhost:${PORT}`);
});

import java.util.*;
class BTreeNode {
static int idCounter = 0;
int id;
int parentId;
ArrayList<Integer> keys = new ArrayList<>();
ArrayList<BTreeNode> children = new ArrayList<>();
boolean leaf;
BTreeNode(boolean isLeaf, int parentId) {
this.id = idCounter++;
this.parentId = parentId;
this.leaf = isLeaf;
}
boolean isFull(int t) {
return keys.size() == 2 * t - 1;
}
void printNode() {
System.out.print("Node ID: " + id);
System.out.print(", Parent ID: " + parentId);
System.out.print(", Keys: " + keys);
System.out.print(", Children: [");
for (int i = 0; i < children.size(); i++) {
System.out.print(children.get(i).id);
if (i != children.size() - 1) System.out.print(", ");
}
System.out.println("]");
}
}
class BTree {
int t; // Minimum degree
BTreeNode root;
BTree(int t) {
this.t = t;
root = new BTreeNode(true, -1);
}
public void insert(int key) {
BTreeNode r = root;
if (r.isFull(t)) {
BTreeNode newRoot = new BTreeNode(false, -1);
newRoot.children.add(r);
r.parentId = newRoot.id;
splitChild(newRoot, 0);
root = newRoot;
insertNonFull(root, key);
} else {
insertNonFull(r, key);
}
}
private void insertNonFull(BTreeNode node, int key) {
int i = node.keys.size() - 1;
if (node.leaf) {
node.keys.add(0); // Dummy key for shifting
while (i >= 0 && key < node.keys.get(i)) {
node.keys.set(i + 1, node.keys.get(i));
i--;
}
node.keys.set(i + 1, key);
} else {
while (i >= 0 && key < node.keys.get(i)) {
i--;
}
i++;
if (node.children.get(i).isFull(t)) {
splitChild(node, i);
if (key > node.keys.get(i)) {
i++;
}
}
insertNonFull(node.children.get(i), key);
}
}
private void splitChild(BTreeNode parent, int i) {
BTreeNode fullChild = parent.children.get(i);
BTreeNode newChild = new BTreeNode(fullChild.leaf, parent.id);
parent.keys.add(i, fullChild.keys.get(t - 1));
for (int j = t; j < 2 * t - 1; j++) {
newChild.keys.add(fullChild.keys.get(j));
}
for (int j = 2 * t - 2; j >= t - 1; j--) {
fullChild.keys.remove(j);
}
if (!fullChild.leaf) {
for (int j = t; j < 2 * t; j++) {
BTreeNode ch = fullChild.children.get(j);
ch.parentId = newChild.id;
newChild.children.add(ch);
}
for (int j = 2 * t - 1; j >= t; j--) {
fullChild.children.remove(j);
}
}
parent.children.add(i + 1, newChild);
}
public void printTree() {
printNodeRecursive(root);
}
private void printNodeRecursive(BTreeNode node) {
node.printNode();
for (BTreeNode child : node.children) {
printNodeRecursive(child);
}
}
}
public class Main {
public static void main(String[] args) {
int order = 5;
int t = (int) Math.ceil(order / 2.0); // For order 5, t = 3
BTree btree = new BTree(t);
int[] numbers = {10, 20, 5, 6, 12, 30, 7, 17};
for (int num : numbers) {
btree.insert(num);
}
btree.printTree();
}
}

import java.util.*;
class BTreeNode {
int id, parentId;
boolean isLeaf;
List<Integer> keys = new ArrayList<>();
List<Integer> children = new ArrayList<>();
BTreeNode(int id, boolean isLeaf, int parentId) {
this.id = id;
this.isLeaf = isLeaf;
this.parentId = parentId;
}
}
class BTree {
BTreeNode root;
Map<Integer, BTreeNode> nodes = new HashMap<>();
void createSpecificTree() {
root = new BTreeNode(0, false, -1);
root.keys = Arrays.asList(25, 65);
root.children = Arrays.asList(1, 2, 3);
nodes.put(0, root);
nodes.put(1, new BTreeNode(1, true, 0));
nodes.get(1).keys = Arrays.asList(11, 17, 24);
nodes.put(2, new BTreeNode(2, true, 0));
nodes.get(2).keys = Arrays.asList(38, 46, 57);
nodes.put(3, new BTreeNode(3, true, 0));
nodes.get(3).keys = Arrays.asList(78, 93);
}
void printTree() {
System.out.print(root.id + " " + root.parentId + " 1");
for (int i = 0; i < root.keys.size(); i++) {
System.out.print(" " + root.keys.get(i) + " " + root.children.get(i));
}
System.out.println(" " + root.children.get(root.children.size() - 1));
for (int id : root.children) {
BTreeNode node = nodes.get(id);
System.out.print(node.id + " " + node.parentId + " -2");
for (int key : node.keys)
System.out.print(" " + key + " -2");
System.out.println();
}
}
}
public class Main {
public static void main(String[] args) {
BTree btree = new BTree();
btree.createSpecificTree();
btree.printTree();
}
}

#include <Wire.h>
#include <LiquidCrystal_I2C.h>
// 🔁 Try 0x27 or 0x3F if LCD not working
LiquidCrystal_I2C lcd(0x27, 16, 2);
// Time variables
unsigned long timer1 = 0;
unsigned long timer2 = 0;
float Time = 0;
float speed = 0;
// Flags
int flag1 = 0;
int flag2 = 0;
// Distance (10 cm)
float distance = 0.10;
// Pins (ESP32)
int ir_s1 = 25;
int ir_s2 = 26;
int buzzer = 13;
void setup() {
Serial.begin(115200);
pinMode(ir_s1, INPUT);
pinMode(ir_s2, INPUT);
pinMode(buzzer, OUTPUT);
// LCD setup
lcd.init();
lcd.backlight();
lcd.setCursor(0, 0);
lcd.print("Speed Detector");
lcd.setCursor(0, 1);
lcd.print("System Ready");
delay(2000);
lcd.clear();
}
void loop() {
int s1 = digitalRead(ir_s1);
int s2 = digitalRead(ir_s2);
// Debug (Serial Monitor)
Serial.print("S1: ");
Serial.print(s1);
Serial.print("  S2: ");
Serial.println(s2);
// Sensor 1 trigger
if (s1 == LOW && flag1 == 0) {
timer1 = millis();
flag1 = 1;
Serial.println("Sensor 1 Triggered");
}
// Sensor 2 trigger
if (s2 == LOW && flag2 == 0) {
timer2 = millis();
flag2 = 1;
Serial.println("Sensor 2 Triggered");
}
// When both sensors triggered → calculate speed
if (flag1 == 1 && flag2 == 1) {
if (timer2 > timer1)
Time = (timer2 - timer1) / 1000.0;
else
Time = (timer1 - timer2) / 1000.0;
if (Time > 0)
speed = (distance / Time) * 3.6;
Serial.print("Speed: ");
Serial.println(speed);
// 🔥 SHOW ON LCD
lcd.clear();
lcd.setCursor(0, 0);
lcd.print("Speed:");
lcd.print(speed, 1);
lcd.print(" Km/h");
lcd.setCursor(0, 1);
if (speed > 20) {
lcd.print("Over Speed!");
digitalWrite(buzzer, HIGH);
} else {
lcd.print("Normal Speed");
digitalWrite(buzzer, LOW);
}
delay(3000);
// Reset
speed = 0;
flag1 = 0;
flag2 = 0;
digitalWrite(buzzer, LOW);
lcd.clear();
}
// Idle display
if (flag1 == 0 && flag2 == 0) {
lcd.setCursor(0, 0);
lcd.print("Waiting...      ");
lcd.setCursor(0, 1);
lcd.print("Place Object    ");
}
delay(100);
}

